SELECT 
FROM product

    is_deleted = 0
    AND category = #{category}

        AND (product_code LIKE CONCAT('%', #{keyword}, '%') OR product_name LIKE CONCAT('%', #{keyword}, '%'))

    AND current_stock >= #{minStock}
    AND current_stock <= #{maxStock}
    AND status = #{status}

ORDER BY create_time DESC
LIMIT #{offset}, #{limit}

SELECT COUNT(*) FROM product

    is_deleted = 0
    AND category = #{category}

        AND (product_code LIKE CONCAT('%', #{keyword}, '%') OR product_name LIKE CONCAT('%', #{keyword}, '%'))

    AND current_stock >= #{minStock}
    AND current_stock <= #{maxStock}
    AND status = #{status}
